from typing import Callable, List, Tuple

def scan_returns(f: Callable[[float], float], x0: float, horizon: int, tolerance: float) -> Tuple[List[float], List[int]]:
    if horizon < 1 or tolerance < 0:
        raise ValueError("invalid horizon or tolerance")
    orbit = [x0]
    returns: List[int] = []
    x = x0
    for n in range(1, horizon + 1):
        x = f(x)
        orbit.append(x)
        if abs(x - x0) < tolerance:
            returns.append(n)
    return orbit, returns

from typing import List, Sequence, Tuple

def logistic(x: float, r: float) -> float:
    return r * x * (1.0 - x)

def estimate_three_cycle(r: float, x0: float, burn_in: int = 1000) -> Tuple[Tuple[float, float, float], float]:
    x = x0
    for _ in range(burn_in):
        x = logistic(x, r)
    phases: List[float] = []
    for _ in range(3):
        phases.append(x)
        x = logistic(x, r)
    residual = abs(x - phases[0])
    return (phases[0], phases[1], phases[2]), residual

