from typing import List, Sequence

def min_plus_matvec(matrix: Sequence[Sequence[float]], vector: Sequence[float]) -> List[float]:
    if not matrix or not vector or any(len(row) != len(vector) for row in matrix):
        raise ValueError("incompatible nonempty dimensions")
    return [min(a + b for a, b in zip(row, vector)) for row in matrix]

def min_plus_power_action(matrix: Sequence[Sequence[float]], vector: Sequence[float], steps: int) -> List[float]:
    state = list(vector)
    for _ in range(steps):
        state = min_plus_matvec(matrix, state)
    return state

